///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_Item);
        await scwin.searchCode();
        scwin.getParentValue();
        if (scwin.gInputSeq !== '') {
            panel_com_srch.hide();
            await scwin.readSync();
            if (scwin.gAcptNo !== '') {
                panel_Button.hide();
            }
        } else {
            // 가우스헤더 셋팅
            const sbmOptions = {
                id : "sbm_dts_SECU_ISU_RSLT",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_SECU_ISU_RSLT=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_SECU_ISU_RSLT.insertRow();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF25125.onpageload" });
    }
};

