 */
scwin.readSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_SECU_ISU_RSLT",
        action : "/InvestStatistics.do",
        ref : "",
        target : "dts_SECU_ISU_RSLT=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(jobType) {
    dts_SECU_ISU_RSLT.setCellData(1, "JOB_TYPE", jobType);
    dts_SECU_ISU_RSLT.setCellData(1, "TRANSTR_EMP_NO", js_emp_no);
    let gTrsCd;
    if (jobType === TR_JOB_INSERT) {
        gTrsCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType === TR_JOB_UPDATE) {
        gTrsCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType === TR_JOB_DELETE) {
        gTrsCd = SCREN_PROCS_TP_CD_04;
    }

    // alert(dts_SECU_ISU_RSLT.text);

    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/InvestStatistics.do",
        ref : "dts_SECU_ISU_RSLT",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.gAcptNo = $c.frame.path("../").scwin.gAcptNo;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    scwin.gInputSeq = $c.frame.path("../").scwin.gInputSeq;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    const vIsurCd = txb_ISUR_CD.getValue();
    if (vIsurCd.length !== 5) {
        await $c.win.alert("[회사코드]를 입력하세요.");
        txb_ISUR_CD.focus();
        return;
    }
    if (cmb_SECU_ISU_METHD_CD.getValue() === "") {
        await $c.win.alert("[발행방법]을 선택하세요.");
        cmb_SECU_ISU_METHD_CD.focus();
        return;
    }
    if (edt_PAY_DD.getValue() === "") {
        await $c.win.alert("[납입일]을 입력하세요.");
        edt_PAY_DD.focus();
        return;
    }
    // alert(dts_nfaith.text);

    let gJobType = TR_JOB_INSERT;
    let LastJob = '저장';
    if (scwin.gInputSeq !== '') {
        gJobType = TR_JOB_UPDATE;
        LastJob = '수정';
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", LastJob))) return;
    await scwin.trs(gJobType);
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (scwin.gInputSeq === '') {
        await $c.win.alert("삭제대상을 선택하세요.");
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '삭제'))) return;
    await scwin.trs(TR_JOB_DELETE);
};
